head.script:
scwin.gVar = {
    "cTabIndex": "",
    "cTagName": "",
}




// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > E > onblur]<br/>컴포넌트가 포커스를 잃을 때 발생합니다.",
    "validation" : [
        "컴포넌트가 포커스를 잃을 때 이벤트가 발생합니다.",
        "readOnly=true, readOnlyFocusEvent=false 인 경우 onblur 이벤트가 발생하지 않습니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // // 조건 설정   
    // let properties = {
    //     tabIndex: scwin.gVar["cTabIndex"],
    //     tagname: scwin.gVar["cTagName"],
    // };

    // let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출    
    $c.gcm.createBasicInput('ev:onblur="scwin.target1_onblur"');  

    // 미지원 조건 비활성화
    wf_sample.getObj("con_tabIndex").setDisabled(true);  
    wf_sample.getObj("con_tagname").setDisabled(true);  
}
